"function model
% TRIMNL_01 : Nonlinear climb + coordinated-turn trim
% Three coupled nonlinear equations in unknowns x = [alpha; T; delta_e]
%   1) q*S*CL*cos(phi) + T*sin(alpha+iT) - W*cos(gamma)          = 0
%   2) T*cos(alpha+iT) - q*S*CD - W*sin(gamma)                   = 0
%   3) q*S*cbar*(Cm0+Cma*alpha+Cmde*delta_e) + T*sin(iT)*zT      = 0
% Solved with a damped Newton iteration (analytic Jacobian), multi-start.

d2r = pi/180;

% ---------------- Parameters ----------------
W    = 230000.0;          % weight, lbf
S    = 2400.0;            % wing area, ft^2
h    = 31000.0;           % altitude, ft
V    = 730.0;             % true airspeed, ft/s
gamD = 3.0;               % climb angle, deg
phiD = 30.0;              % bank angle, deg

CL0  = 0.15;  CLa = 5.2;  CLde = 0.35;      % 1/rad
CD0  = 0.021; kk  = 0.043;                  % parabolic drag
rho0 = 0.0023769; H = 23800.0;              % slug/ft^3, ft (exponential atm)
iT   = 2.5*d2r;    zT = 2.0;                % thrust incidence (rad), arm (ft)
Cm0  = 0.02;  Cma = -0.3;  Cmde = -0.85;    % 1/rad
cbar = 17.0;                                % mean chord, ft

gam  = gamD*d2r;
phi  = phiD*d2r;

rho  = rho0*exp(-h/H);
q    = 0.5*rho*V^2;
qS   = q*S;

p = struct('W',W,'qS',qS,'gam',gam,'phi',phi, ...
           'CL0',CL0,'CLa',CLa,'CLde',CLde,'CD0',CD0,'kk',kk, ...
           'iT',iT,'zT',zT,'Cm0',Cm0,'Cma',Cma,'Cmde',Cmde,'cbar',cbar);

% ---------------- Damped Newton (multi-start) ----------------
tol   = 1e-6;                                  % residual tol (lbf scale)
guess = [ 5.0*d2r  28000  -0.5*d2r ;
          3.0*d2r  15000   1.0*d2r ;
          8.0*d2r  45000  -2.0*d2r ];

x  = guess(1,:)';
ok = false;
for g = 1:size(guess,1)
    x = guess(g,:)';
    for it = 1:100
        F  = resfun(x,p);
        nF = norm(F);
        if nF < tol, break; end
        try
            dx = -jacfun(x,p)\F;
        catch
            x = x + 1e-4*randn(3,1).*max(abs(x),1);   % kick out of singular point
            continue;
        end
        lam = 1.0;                                    % backtracking line search
        for ls = 1:60
            if norm(resfun(x+lam*dx,p)) < nF, break; end
            lam = 0.5*lam;
        end
        step = lam*dx;
        x    = x + step;
        if norm(step) < 1e-14, break; end
    end
    if norm(resfun(x,p)) < tol, ok = true; break; end
end
if ~ok
    warning('Newton did not fully converge; residual = %.3e', norm(resfun(x,p)));
end

% ---------------- Results ----------------
alpha = x(1);   T = x(2);   de = x(3);
n     = cos(gam)/cos(phi);                  % load factor, coordinated turn

result = struct( ...
    'alpha_trim_deg',   alpha/d2r, ...
    'thrust_lbf',       T, ...
    'delta_e_trim_deg', de/d2r, ...
    'load_factor',      n);

fid = fopen('result.json','w');
if fid < 0, error('Cannot open result.json for writing.'); end
fwrite(fid, jsonencode(result));
fclose(fid);

% ---------------- Report ----------------
fprintf('rho = %.6e slug/ft^3, q = %.4f psf, qS = %.1f lbf\n', rho, q, qS);
fprintf('alpha_trim   = %12.6f deg  (expect 0.5..10)\n', alpha/d2r);
fprintf('thrust       = %12.2f lbf  (expect 5000..60000)\n', T);
fprintf('delta_e_trim = %12.6f deg\n', de/d2r);
fprintf('load factor  = %12.6f\n', n);
fprintf('final residual norm = %.3e\n', norm(resfun(x,p)));
end

% ================= Residuals =================
function F = resfun(x,p)
alpha = x(1); T = x(2); de = x(3);
CL = p.CL0 + p.CLa*alpha + p.CLde*de;
CD = p.CD0 + p.kk*CL^2;
th = alpha + p.iT;                       % thrust angle vs horizon (body pitch = alpha)
F = [ p.qS*CL*cos(p.phi) + T*sin(th) - p.W*cos(p.gam) ;   % vertical
      T*cos(th) - p.qS*CD - p.W*sin(p.gam) ;              % along flight path
      p.qS*p.cbar*(p.Cm0 + p.Cma*alpha + p.Cmde*de) ...
          + T*sin(p.iT)*p.zT ];                          % pitch about CG
end

% ================= Analytic Jacobian =================
function J = jacfun(x,p)
alpha = x(1); T = x(2); de = x(3);
CL = p.CL0 + p.CLa"
